const assert=require('node:assert/strict');
const api=require('./scoreboard-mutation-v2.js');
const map=new Map();const storage={getItem:k=>map.get(k)||null,setItem:(k,v)=>map.set(k,v)};
const s=api.createStore(storage);
const m=s.createMutation('A',{mutationId:'m1',entityType:'record',operation:'add',payload:{points:5}});
assert.equal(s.createMutation('A',{mutationId:'m1',entityType:'record',operation:'add',payload:{points:5}}).sequence,m.sequence);
assert.throws(()=>s.createMutation('A',{mutationId:'m1',entityType:'record',operation:'add',payload:{points:6}}),/different payload/);
assert.equal(s.getPending('B').length,0);
s.markUnknown('A','m1');assert.equal(s.read('A').mutations[0].status,'UNKNOWN');
s.acknowledge('A',['m1']);assert.equal(s.read('A').mutations[0].status,'ACKNOWLEDGED');
s.createMutation('A',{mutationId:'old',entityType:'record',operation:'add',payload:{points:2}});
const reset=s.startReset('A','reset-1');assert.equal(s.startReset('A','reset-1').resetRequestId,reset.resetRequestId);
s.confirmReset('A','reset-1');assert.equal(s.read('A').epoch,1);assert.equal(s.read('A').mutations.find(x=>x.mutationId==='old').status,'RECOVERY_REQUIRED');
assert.equal(s.createMutation('A',{mutationId:'new',entityType:'record',operation:'add',payload:{points:1}}).resetEpoch,1);
console.log('Scoreboard mutation V2 regression tests: PASS');
